const log = {
  lines: [],
  get last() {
    return this.lines[this.lines.length - 1];
  },
  set last(text) {
    this.lines.push(text);
    return "saved";
  },
};

const result = (log.last = "a");
log.last += "b";
const copy = { ...log };
log.last = "c";

console.log(result);
console.log(log.lines.join(","));
console.log(copy.last);
console.log(copy.lines.length);
